/bin/bash -lc "python - <<'PY'
import sim, numpy as np
s=sim.Sim()
# try setting ctrl to one vector and seeing actual after steps
target=np.array([0,0.7,0,-1.52,0,2.12,-0.7853])
for label in ['all','half','single']:
    s.reset();
    if label=='all':
        s.data.ctrl[:7]=target
    elif label=='half':
        s.data.ctrl[:7]=target*0.5
    else:
        s.data.ctrl[1]=0.7
    for _ in range(300): s.step(1)
    print(label,'actual',s.data.qpos[:7])
    print('drawer',s.drawer_open_amount())
PY"

